  border-radius: var(--radius-md);
  font-size: var(--text-xs); font-family: var(--font-mono);
  animation: msg-in 180ms cubic-bezier(0.16,1,0.3,1) both;
  transition: border-color var(--transition-interactive), opacity var(--transition-interactive);
}
.tool-call.running { border-color: var(--color-primary); }
.tool-call.done    { border-color: var(--color-success); opacity: 0.65; }
.tool-call.error   { border-color: var(--color-error); }

.tool-icon { flex-shrink: 0; margin-top: 1px; width: 14px; height: 14px; }
.tool-icon.running { color: var(--color-primary); animation: spin 1.1s linear infinite; }
.tool-icon.done    { color: var(--color-success); }
.tool-icon.error   { color: var(--color-error); }
@keyframes spin { to { transform: rotate(360deg); } }

.tool-info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.tool-name   { font-weight: 600; color: var(--color-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tool-detail { color: var(--color-text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 55ch; }

/* ---- THINKING ---- */
.thinking-row {
  display: flex; align-items: center; gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  background: var(--color-surface); border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: var(--text-sm); color: var(--color-text-muted);
  animation: msg-in 200ms cubic-bezier(0.16,1,0.3,1) both;
}
.thinking-dots { display: flex; gap: var(--space-1); align-items: center; }
.thinking-dots span {
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--color-primary);
  animation: thinking-bounce 1.2s ease-in-out infinite;
}
.thinking-dots span:nth-child(2) { animation-delay: 0.15s; }
.thinking-dots span:nth-child(3) { animation-delay: 0.3s; }
@keyframes thinking-bounce {
  0%, 80%, 100% { transform: scale(0.65); opacity: 0.35; }
  40%           { transform: scale(1); opacity: 1; }
}

/* ---- STREAM CURSOR ---- */
.stream-cursor::after {
  content: '▋';
  animation: blink 1s step-end infinite;
  color: var(--color-primary); font-size: 0.9em; margin-left: 1px;
}
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }

/* ---- INPUT AREA ---- */
.input-area {
  flex-shrink: 0;
  padding: var(--space-4) var(--space-4) var(--space-5);
  border-top: 1px solid var(--color-border);
  background: var(--color-surface);
}
.input-inner { max-width: var(--content-default); margin: 0 auto; display: flex; flex-direction: column; gap: var(--space-2); }
.input-box {
  display: flex; align-items: flex-end; gap: var(--space-2);
  background: var(--color-surface-offset);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--space-2) var(--space-2) var(--space-2) var(--space-4);
  transition: border-color var(--transition-interactive), box-shadow var(--transition-interactive);
}
.input-box:focus-within {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px oklch(from var(--color-primary) l c h / 0.12);
}
#msg-input {
  flex: 1; background: transparent; border: none; outline: none;
  resize: none; font-family: var(--font-body); font-size: var(--text-base);
  color: var(--color-text); line-height: 1.55;
  max-height: 180px; min-height: 36px;
  padding: var(--space-1) 0;
}
#msg-input::placeholder { color: var(--color-text-faint); }
.send-btn {
  display: flex; align-items: center; justify-content: center;
  width: 38px; height: 38px;
  border-radius: var(--radius-lg);
  background: var(--color-primary); color: var(--color-text-inverse);
  flex-shrink: 0;
  transition: background var(--transition-interactive), transform var(--transition-interactive), opacity var(--transition-interactive);
}
.send-btn:hover:not(:disabled)  { background: var(--color-primary-hover); }
.send-btn:active:not(:disabled) { transform: scale(0.93); }
.send-btn:disabled               { opacity: 0.3; cursor: not-allowed; }
.input-hint { font-size: var(--text-xs); color: var(--color-text-faint); text-align: center; }

/* ---- SCROLLBAR ---- */
.messages-scroll::-webkit-scrollbar { width: 5px; }
.messages-scroll::-webkit-scrollbar-track { background: transparent; }
.messages-scroll::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: var(--radius-full); }
.messages-scroll::-webkit-scrollbar-thumb:hover { background: var(--color-surface-dynamic); }

/* ---- TOAST ---- */
.toast-container {
  position: fixed; bottom: 90px; left: 50%; transform: translateX(-50%);
  z-index: 100; display: flex; flex-direction: column; gap: var(--space-2);
  pointer-events: none;
}
.toast {
  pointer-events: auto;
  padding: var(--space-3) var(--space-5);
  background: var(--color-surface-2); border: 1px solid var(--color-border);
  border-radius: var(--radius-lg); font-size: var(--text-sm);
  color: var(--color-text-muted); box-shadow: var(--shadow-md);
  display: flex; align-items: center; gap: var(--space-3);
  animation: toast-in 240ms cubic-bezier(0.16,1,0.3,1) both;
  white-space: nowrap;
}
.toast.error { border-color: var(--color-error); color: var(--color-error); }
.toast.info  { border-color: var(--color-primary); color: var(--color-primary); }
@keyframes toast-in { from { opacity:0; transform: translateY(8px) scale(0.96); } to { opacity:1; transform: translateY(0) scale(1); } }

/* ---- RESPONSIVE ---- */
@media (max-width: 640px) {
  .topbar { padding: var(--space-2) var(--space-4); }
  .logo-text { display: none; }
  .conn-badge span { display: none; }
  .messages-scroll { padding: var(--space-4) var(--space-3); }
  .input-area { padding: var(--space-3) var(--space-3) var(--space-4); }
  .msg.user .msg-body { max-width: 95%; }
}
</style>
