// ============================================================
(function () {
  const btn  = document.querySelector('[data-theme-toggle]');
  const root = document.documentElement;
  let theme  = root.getAttribute('data-theme') || 'dark';

  const SUN  = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>`;
  const MOON = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>`;

  function apply(t) {
    theme = t;
    root.setAttribute('data-theme', t);
    if (btn) { btn.innerHTML = t === 'dark' ? SUN : MOON; btn.setAttribute('aria-label', `Switch to ${t === 'dark' ? 'light' : 'dark'} mode`); }
  }

  apply(theme);
  if (btn) btn.addEventListener('click', () => apply(theme === 'dark' ? 'light' : 'dark'));
})();

// ============================================================
// DOM REFS
// ============================================================
const messagesInner  = document.getElementById('messages-inner');
const messagesScroll = document.getElementById('messages-scroll');
const msgInput       = document.getElementById('msg-input');
const sendBtn        = document.getElementById('send-btn');
const connDot        = document.getElementById('conn-dot');
const connLabel      = document.getElementById('conn-label');
const elapsedBar     = document.getElementById('elapsed-bar');
const elapsedTime    = document.getElementById('elapsed-time');
const elapsedTaskId  = document.getElementById('elapsed-task-id');
const stopBtn        = document.getElementById('stop-btn');
const toastContainer = document.getElementById('toast-container');

// ============================================================
// STATE
// ============================================================
let currentTaskId   = null;
let currentSSE      = null;
let elapsedInterval = null;
let taskStartTime   = null;
let isStreaming     = false;
let pollInterval    = null;
let pollCursor      = 0;
let reconnectTimer  = null;
let reconnectCount  = 0;
let _pollBody       = null;
let _pollThinking   = null;
const activeToolCalls  = {};
const MAX_RECONNECT    = 8;
const RECONNECT_BASE   = 1500;

// ============================================================
// UTILS
// ============================================================
function formatElapsed(ms) {
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60), rs = s % 60;
  if (m < 60) return `${m}m ${rs}s`;
  return `${Math.floor(m / 60)}h ${m % 60}m`;
}

function scrollToBottom(force = false) {
  const el = messagesScroll;
  const near = el.scrollHeight - el.scrollTop - el.clientHeight < 160;
  if (force || near) el.scrollTop = el.scrollHeight;
}

function setConn(state, label) {
  connDot.className = `conn-dot ${state}`;
  connLabel.textContent = label;
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;')
    .replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
}

// ============================================================
// TOAST
// ============================================================
function showToast(msg, type = 'info', ms = 4500) {
  const t = document.createElement('div');
  t.className = `toast ${type}`;
  t.textContent = msg;
  toastContainer.appendChild(t);
  setTimeout(() => {
    t.style.cssText = 'opacity:0;transform:translateY(8px);transition:300ms ease';
    setTimeout(() => t.remove(), 300);
  }, ms);
}

// ============================================================
// TEXTAREA
// ============================================================
msgInput.addEventListener('input', () => {
  msgInput.style.height = 'auto';
  msgInput.style.height = Math.min(msgInput.scrollHeight, 180) + 'px';
  sendBtn.disabled = !msgInput.value.trim() || isStreaming;
});

msgInput.addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); if (!sendBtn.disabled) sendMessage(); }
});

// ============================================================
// HINT CHIPS
// ============================================================
document.querySelectorAll('.hint-chip').forEach(chip =>
  chip.addEventListener('click', () => {
    msgInput.value = chip.dataset.hint;
    msgInput.dispatchEvent(new Event('input'));
    msgInput.focus();
  })
);

// ============================================================
// RENDER HELPERS
// ============================================================
function hideWelcome() {
  const w = document.getElementById('welcome-screen');
  if (w) w.remove();
}

function appendUserMessage(text) {
  hideWelcome();
  const div = document.createElement('div');
  div.className = 'msg user';
  div.innerHTML = `
    <div class="msg-header">
      <span class="msg-role user">You</span>
      <span>${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span>
    </div>
    <div class="msg-body">${escapeHtml(text)}</div>`;
  messagesInner.appendChild(div);
  scrollToBottom(true);
}

function createAssistantBlock() {
  const div = document.createElement('div');
  div.className = 'msg assistant';
  div.innerHTML = `
    <div class="msg-header">
      <span class="msg-role assistant">Knight</span>
      <span>${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span>
    </div>
    <div class="tool-calls" id="tc-container"></div>
    <div class="thinking-row" id="thinking-row">
      <div class="thinking-dots"><span></span><span></span><span></span></div>
      <span>Thinking…</span>
    </div>
    <div class="msg-body stream-cursor" id="stream-body"></div>`;
  messagesInner.appendChild(div);
  scrollToBottom(true);
  return div;
}

function renderToolCall(id, name, detail, status) {
  const container = document.getElementById('tc-container');
  if (!container) return;
  const ICONS = {
    running: `<svg class="tool-icon running" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/></svg>`,
    done:    `<svg class="tool-icon done"    viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>`,
    error:   `<svg class="tool-icon error"   viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>`,
  };
  let el = activeToolCalls[id];
  if (!el) {
    el = document.createElement('div');
    el.className = `tool-call ${status}`;
    el.innerHTML = `
      <div id="ti-${id}">${ICONS[status] || ICONS.running}</div>
      <div class="tool-info">
        <span class="tool-name"  id="tn-${id}">${escapeHtml(name)}</span>
        <span class="tool-detail" id="td-${id}">${escapeHtml(detail||'')}</span>
      </div>`;
    container.appendChild(el);
    activeToolCalls[id] = el;
  } else {
    el.className = `tool-call ${status}`;
    const ti = document.getElementById(`ti-${id}`);
    if (ti) ti.innerHTML = ICONS[status] || ICONS.running;
    const td = document.getElementById(`td-${id}`);
    if (td && detail) td.textContent = detail;
  }
  scrollToBottom();
}

// ============================================================
// ELAPSED TIMER
// ============================================================
function startElapsed(taskId) {
  taskStartTime = Date.now();
  elapsedBar.classList.remove('hidden');
  elapsedTaskId.textContent = `Task: ${taskId.slice(0, 8)}…`;
  clearInterval(elapsedInterval);
  elapsedInterval = setInterval(() => {
    elapsedTime.textContent = formatElapsed(Date.now() - taskStartTime);
  }, 500);
}

function stopElapsed() {
  clearInterval(elapsedInterval);
  elapsedInterval = null;
  setTimeout(() => elapsedBar.classList.add('hidden'), 1200);
}

// ============================================================
// SEND
// ============================================================
async function sendMessage() {
  const text = msgInput.value.trim();
  if (!text || isStreaming) return;

  msgInput.value = '';
  msgInput.style.height = 'auto';
  sendBtn.disabled = true;
  isStreaming = true;
  pollCursor  = 0;
  reconnectCount = 0;
  Object.keys(activeToolCalls).forEach(k => delete activeToolCalls[k]);

  appendUserMessage(text);
  const block      = createAssistantBlock();
  const streamBody = block.querySelector('#stream-body');
  const thinkRow   = block.querySelector('#thinking-row');

  setConn('streaming', 'Connecting…');

  try {
    const res = await fetch('/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: text }),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);

    const { task_id } = await res.json();
    currentTaskId = task_id;
    startElapsed(task_id);
    setConn('streaming', 'Streaming');
    connectSSE(task_id, streamBody, thinkRow);

  } catch (err) {
    finishStreaming(streamBody, thinkRow);
    streamBody.textContent = `Error: ${err.message}`;
    streamBody.classList.remove('stream-cursor');
    showToast(err.message, 'error');
    setConn('error', 'Error');
  }
}

// ============================================================
// SSE
// ============================================================
function connectSSE(taskId, streamBody, thinkRow) {
  clearTimeout(reconnectTimer); reconnectTimer = null;
  if (currentSSE) { currentSSE.close(); currentSSE = null; }

  const sse = new EventSource(`/api/task/${taskId}/stream?cursor=${pollCursor}`);
  currentSSE = sse;

  sse.onopen = () => { setConn('streaming', 'Streaming'); reconnectCount = 0; };
  sse.onmessage = e => handleEvent(e.data, streamBody, thinkRow);

  ['delta','tool_start','tool_end','tool_error','done','error','heartbeat'].forEach(name =>
    sse.addEventListener(name, e => {
      try { const o = JSON.parse(e.data); o._event = name; processEvent(o, streamBody, thinkRow); }
      catch { processEvent({ _event: name, text: e.data }, streamBody, thinkRow); }
    })
  );

  sse.onerror = () => {
    sse.close(); currentSSE = null;
    setConn('error', 'Reconnecting…');
    startPolling(taskId, streamBody, thinkRow);

    if (reconnectCount < MAX_RECONNECT) {
      reconnectCount++;
      const delay = Math.min(RECONNECT_BASE * Math.pow(1.5, reconnectCount - 1), 15000);
      reconnectTimer = setTimeout(() => { stopPolling(); connectSSE(taskId, streamBody, thinkRow); }, delay);
    } else {
      showToast('SSE failed — switched to polling.', 'info');
    }
  };
}

// ============================================================
// EVENT PROCESSING
// ============================================================
function handleEvent(data, streamBody, thinkRow) {
  try { processEvent(JSON.parse(data), streamBody, thinkRow); }
  catch {
    hideThinking(thinkRow);
    streamBody.textContent += data;
    scrollToBottom();
  }
}

function hideThinking(thinkRow) {
  if (thinkRow && thinkRow.style.display !== 'none') thinkRow.style.display = 'none';
}

function processEvent(obj, streamBody, thinkRow) {
  const evt = obj._event || obj.type || obj.event || '';
  const cursor = obj.cursor ?? obj.seq ?? null;
  if (cursor !== null) pollCursor = cursor;

  switch (evt) {
    case 'delta': {
      hideThinking(thinkRow);
      streamBody.textContent += (obj.text || obj.delta || obj.content || '');
      scrollToBottom();
      break;
    }
    case 'tool_start': {
      const id = obj.id || obj.tool_call_id || obj.name || 'tool';
      renderToolCall(id, obj.name || obj.tool || id,
        obj.input ? JSON.stringify(obj.input).slice(0, 90) : '', 'running');
      break;
    }
    case 'tool_end': {
      const id = obj.id || obj.tool_call_id || obj.name || 'tool';
      renderToolCall(id, obj.name || obj.tool || id,
        obj.output ? String(obj.output).slice(0, 90) : 'Done', 'done');
      break;
    }
    case 'tool_error': {
      const id = obj.id || obj.tool_call_id || obj.name || 'tool';
      renderToolCall(id, obj.name || obj.tool || id, obj.error || 'Error', 'error');
      break;
    }
    case 'heartbeat':
      break; // cursor already updated above
    case 'done':
      finishStreaming(streamBody, thinkRow);
      break;
    case 'error':
      streamBody.textContent += `\n\n[Error: ${obj.message || obj.error || 'Unknown'}]`;
      streamBody.classList.remove('stream-cursor');
      showToast(obj.message || 'Stream error', 'error');
      finishStreaming(streamBody, thinkRow);
      break;
    default:
      if (obj.text || obj.delta || obj.content) {
        hideThinking(thinkRow);
        streamBody.textContent += (obj.text || obj.delta || obj.content);
        scrollToBottom();
      }
  }
}

// ============================================================
// FINISH
// ============================================================
function finishStreaming(streamBody, thinkRow) {
  isStreaming = false;
  clearTimeout(reconnectTimer); reconnectTimer = null;
  stopPolling();
  if (currentSSE) { currentSSE.close(); currentSSE = null; }
  if (streamBody) streamBody.classList.remove('stream-cursor');
  if (thinkRow && thinkRow.parentNode) thinkRow.remove();
  stopElapsed();
  setConn('connected', 'Ready');
  sendBtn.disabled = !msgInput.value.trim();
  scrollToBottom(true);
  currentTaskId = null;
}

// ============================================================
// POLLING FALLBACK
// ============================================================
function startPolling(taskId, streamBody, thinkRow) {
  if (pollInterval) return;
  _pollBody = streamBody; _pollThinking = thinkRow;
  pollInterval = setInterval(() => doPoll(taskId), 2000);
}

function stopPolling() { clearInterval(pollInterval); pollInterval = null; }

async function doPoll(taskId) {
  try {
    const res = await fetch(`/api/task/${taskId}/poll?cursor=${pollCursor}`);
    if (!res.ok) return;
    const data = await res.json();
    if (Array.isArray(data.events)) data.events.forEach(e => processEvent(e, _pollBody, _pollThinking));
    if (data.cursor != null) pollCursor = data.cursor;
    if (data.done) { stopPolling(); finishStreaming(_pollBody, _pollThinking); }
  } catch { /* ignore */ }
}

// ============================================================
// STOP BUTTON
// ============================================================
stopBtn.addEventListener('click', async () => {
  if (!currentTaskId) return;
  try { await fetch(`/api/task/${currentTaskId}/stop`, { method: 'POST' }); }
  catch { /* best effort */ }
  showToast('Stop requested — waiting for task to acknowledge…', 'info');
});

// ============================================================
// SEND BUTTON
// ============================================================
sendBtn.addEventListener('click', sendMessage);

// Init
setConn('connected', 'Ready');
sendBtn.disabled = true;
</script>
</body>
</html>
```

***

## What this implements

### Task flow
The frontend does exactly what your architecture requires . On send, it POSTs to `/api/chat`, extracts `task_id` from the response JSON, then immediately opens an `EventSource` to `/api/task/{id}/stream?cursor=0`. The cursor is forwarded on every reconnect so the server can resume from where the client left off.

### SSE + polling hybrid reconnection
If the `EventSource` fires `onerror`, the client does two things simultaneously: it starts a **2-second polling loop** against `/api/task/{id}/poll?cursor={n}` to bridge the gap, and schedules an SSE reconnect with **exponential backoff** (1.5× per attempt, capped at 15 seconds, max 8 attempts). Once SSE reconnects successfully, polling stops. After 8 failed attempts it logs a toast and stays on polling permanently.

### Event types handled
The listener registers named SSE event handlers for `delta`, `tool_start`, `tool_end`, `tool_error`, `done`, `error`, and `heartbeat`. Each event carries an optional `cursor`/`seq` field that advances the poll cursor. The poll endpoint's response format is `{ events: [...], cursor: N, done: bool }`.

### Real-time tool execution display
`tool_start` renders an animated spinning badge with the tool name and truncated input. `tool_end` replaces it with a green check and a summary of the output. `tool_error` shows a red ✕. All tool cards stay visible in the message so the user can see the full execution trace.

### Elapsed timer
A persistent status bar appears below the top bar the moment a task starts. It shows elapsed time with `tabular-nums` formatting (`0s` → `4m 32s` → `1h 12m`), the truncated task ID, and a **Stop** button that fires `POST /api/task/{id}/stop`. The bar disappears 1.2 seconds after the stream finishes.

### Stop button
Fires a best-effort `POST /api/task/{id}/stop`. The UI does not forcibly terminate — it waits for the server to send `done` or `error` through the stream, which keeps the state machine clean.
